import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') ptr++;
            return hasNextByte();
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ') b = readByte();
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            int val = 0;
            while (b >= '0' && b <= '9') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -val : val;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        if (!scanner.hasNext()) return;
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int c = scanner.nextInt();

        int[] a = new int[n + 1];
        long[] pref = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            a[i] = scanner.nextInt();
            pref[i] = pref[i - 1] + a[i];
        }

        long totalSum = pref[n];

        // dp[i] representará a menor soma coberta usando j etiquetas no prefixo i
        long[] prev = new long[n + 1];
        long[] curr = new long[n + 1];

        for (int j = 1; j <= k; j++) {
            int minI = j * c;
            int maxI = n - (k - j) * c;

            for (int i = minI; i <= maxI; i++) {
                long sumC = pref[i] - pref[i - c];
                long valCover = prev[i - c] + sumC;
                if (i == minI) {
                    curr[i] = valCover;
                } else {
                    curr[i] = Math.min(curr[i - 1], valCover);
                }
            }

            long[] temp = prev;
            prev = curr;
            curr = temp;
        }

        long minCovered = prev[n];
        long maxUncovered = totalSum - minCovered;

        System.out.println(maxUncovered);
    }
}
